INSERT INTO `film` (`id`, `name`, `fecha`, `genre`, `directors`, `actors`, `description`) VALUES
(292, 'Akira', '1988', 'Ciencia ficción', 'Katsuhiro Otomo', 'Animación', 'Año 2019. Neo-Tokyo es una ciudad construida sobre las ruinas de la antigua capital japonesa destruida tras la Tercera Guerra Mundial. Japón es un país al borde del colapso que sufre continuas crisis políticas. En secreto, un equipo de científicos ha reanudado por orden del ejército un experimento para encontrar a individuos que puedan controlar el arma definitiva: una fuerza denominada \"la energía absoluta\". '),
(325, 'Origen', '2010', 'Ciencia ficción', 'Christopher Nolan', 'Leonardo DiCaprio, Joseph Gordon-Levitt, Ellen Page, Tom Hardy, Ken Watanabe, ...', 'Dom Cobb (DiCaprio) es un experto en el arte de apropiarse, durante el sueño, de los secretos del subconsciente ajeno. La extraña habilidad de Cobb le ha convertido en un hombre muy cotizado en el mundo del espionaje, pero también lo ha condenado a ser un fugitivo y, por consiguiente, a renunciar a llevar una vida normal. '),
(326, 'Matrix', '1999', 'Ciencia ficción', 'Hermanas Wachowski', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne, ... ', 'Thomas Anderson es un brillante programador de una respetable compañía de software. Pero fuera del trabajo es Neo, un hacker que un día recibe una misteriosa visita... '),
(327, 'Pulp Fiction', '1984', 'Thriller', 'Quentin Tarantino', 'Jonh Travolta, Samuel L.Jackson, Uma Thurman, Bruce Willis, ...', 'Jules y Vincent, dos asesinos a sueldo con no demasiadas luces, trabajan para el gángster Marsellus Wallace. Vincent le confiesa a Jules que Marsellus le ha pedido que cuide de Mia, su atractiva mujer. Jules le recomienda prudencia porque es muy peligroso sobrepasarse con la novia del jefe. Cuando llega la hora de trabajar, ambos deben ponerse \"manos a la obra\". Su misión: recuperar un misterioso maletín.'),
(328, 'Pacific Rim', '2013', 'Ciencia ficción', 'Guillermo del Toro', 'Charlie Hunnam, Idris Elba, Rinko Kikuchi, Charlie Day, ...', 'Cuando legiones de monstruosas criaturas, denominadas Kaiju, comienzan a salir del mar, se inicia una guerra que acabará con millones de vidas y que consumirá los recursos de la humanidad durante interminables años. Para combatir a los Kaiju gigantes diseñan un tipo especial de arma: enormes robots, llamados Jaegers, que son controlados '),
(329, 'El Padrino', '1972', 'Drama, Mafia', 'Francis Ford Coppola', 'Marlon Brando, Al Pacino, James Caan, Robert Duvall, Diane Keaton, ...', 'América, años 40. Don Vito Corleone (Marlon Brando) es el respetado y temido jefe de una de las cinco familias de la mafia de Nueva York. Tiene cuatro hijos: Connie (Talia Shire), el impulsivo Sonny (James Caan), el pusilánime Fredo (John Cazale) y Michael (Al Pacino), que no quiere saber nada de los negocios de su padre.'),
(330, 'Viaje de Chihiro', '2001', 'Animación, Fantasía', 'Hayao Miyazaki', 'Animación', 'Chihiro es una niña de diez años que viaja en coche con sus padres. Después de atravesar un túnel, llegan a un mundo fantástico, en el que no hay lugar para los seres humanos, sólo para los dioses de primera y segunda clase. Cuando descubre que sus padres han sido convertidos en cerdos, Chihiro se siente muy sola y asustada.'),
